import { Color } from 'three/webgpu';
import { onStart } from '../loop.ts';
import { defineKind, spawn } from '../entity/entity.ts';
import { me } from '../player/state.ts';
import { stepSurfaceAt } from '../render/locomotion-surfaces.ts';
import { emit } from '../render/particles.ts';
defineKind('review-footfeel', { update: 39 });
onStart(() => {let wasGrounded=false; spawn({kind:'review-footfeel', update(){const p=me.body?.position; if(!p)return; const grounded=me.coyote>0; if(grounded&&!wasGrounded&&stepSurfaceAt(p.x,p.y,p.z)==='sand') emit({x:p.x,y:p.y,z:p.z,vx:0,vy:1,vz:0,life:0.3,size:0.08,color:new Color(0xddccaa)}); wasGrounded=grounded;}});});

